{
  "iteration": 6,
  "pcvs": [
    {
      "name": "default_options",
      "expression": "int(tokenization_kwargs is None)",
      "rationale": "Separates the entry state containing the exceptional initialization cost."
    },
    {
      "name": "longer_than_40_chars",
      "expression": "int(len(prompt if isinstance(prompt, str) else prompt['prompt']) > 40)",
      "rationale": "Separates short prompts from the medium and long prompts with substantially higher observed processing costs."
    },
    {
      "name": "longer_than_100_chars",
      "expression": "int(len(prompt if isinstance(prompt, str) else prompt['prompt']) > 100)",
      "rationale": "Allows an independent cost increment for long prompts instead of forcing a continuous length relationship."
    },
    {
      "name": "special_tokens_without_truncation",
      "expression": "int((tokenization_kwargs or {}).get('add_special_tokens', True) and 'truncate_prompt_tokens' not in (tokenization_kwargs or {}))",
      "rationale": "Separates the observed additional cost when special tokens are enabled without explicit truncation."
    }
  ],
  "hypothesis": "Observed costs form short, medium, and long prompt groups with small within-group variation. Explicit length regimes may explain these costs better than continuous character and word-count models while retaining six distinct states."
}
